/**
 * P46 ر4-أ «محور التقارير» — «ملف الدبلوم» («أثرُ الدبلوم»)
 *  <DiplomaCards>      داخل /me/reports  (#diploma)   بطاقة لكل شعبة دبلوم: خريطة الوحدات ✓●○ · «نبض هذا الأسبوع» · «أريد التقرير الكامل هذا الأسبوع» · «أغلق الوحدة بتقريرها» · «وحدات الدبلوم»
 *  <UnitsPanel>        داخل البطاقة                   قائد الدبلوم يكتب الوحدات (أو يستوردها من تصميم «هندسة البرامج») — المغلقة لا تُحذف
 *  <PulseEditor>       /me/reports/[id] · /admin      نصف صفحة: الأرقام جاهزة · ما تمّ · من يحتاج انتباهًا · «ما الذي تغيّر؟» (سلسلة الانتباه) · ما يلزمنا
 *  <UnitEditor>        /me/reports/[id] · /admin      ستة أقسام: بيانات الوحدة · التنفيذ · التقييم · كشف الوحدة (درجات + شواهد م/ب/ي/ح + قرار) · سلسلة الانتباه · ما بعد الوحدة · الاعتماد
 *  <UnitDoc>           المطبوع A4                      وثيقة واحدة بمفتاح الشواهد
 *  <ProgramUnitsStrip> /programs/[id] (عام)           «خريطة الوحدات» للزائر: عناوين ونواتج وحالة — بلا أسماء
 *  القاعدة: الأرقام والأسماء والشواهد من أَثَر؛ الحكم والقرار للمعلّم؛ الاعتماد للطاقم؛ واعتماد تقرير الوحدة = إغلاقها.
 */
import { useCallback, useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import { Icon } from '../../lib/ui/icons';
import { P46_NAMES_AR, R4_NAMES_AR, UNIT_STATE_AR, UNIT_TOOLS_AR, ATTENTION_CHANGE, ATTENTION_CHANGE_AR, UNIT_DECISION, UNIT_DECISION_AR, EVIDENCE_MARKS_AR, UNIT_MAX, UNIT_TITLE_MAX, UNIT_OUTCOME_MAX, PULSE_MAX_ATTENTION, PULSE_TEXT_MAX, TEXT_MAX, SHORT_MAX, LINE_MAX, MAX_LIST, GRADE_KEY_AR, PASS_MARK, fmtDayAr, summativeStats, outcomePctSuggested, type Unit, type PulseBody, type PulseComputed, type UnitBody, type UnitComputed, type UnitStudent, type DiplomaCard, type Phrase } from '../../lib/reports/registry';
import { MR_CSS, MR_PRINT_CSS } from './MissionReport';
import dynamic from 'next/dynamic';
const ProfilesPanel = dynamic(() => import('./DiplomaProfile').then(m => m.ProfilesPanel), { ssr: false });   // ر4-ب «كشف الكفايات»

type Tok = () => Promise<string>;
async function api(tok: Tok | null, path: string, body?: any) { const tk = tok ? await tok() : ''; const h: any = { 'Content-Type': 'application/json' }; if (tk) h.Authorization = `Bearer ${tk}`; const r = await fetch(path, body ? { method: 'POST', headers: h, body: JSON.stringify(body) } : { headers: h, cache: 'no-store' }); return r.json().catch(() => ({ success: false, error: 'استجابة غير صالحة' })); }
const TONE: Record<string, string> = { draft: 'g', submitted: 'b', approved: 't', returned: 'o' };
const STATE_MARK: Record<string, string> = { closed: '✓', current: '●', upcoming: '○' };
const upd = <O,>(o: O, path: (string | number)[], v: any): O => { const c: any = Array.isArray(o) ? [...(o as any)] : { ...(o as any) }; if (path.length === 1) { c[path[0]] = v; return c; } c[path[0]] = upd(c[path[0]] ?? (typeof path[1] === 'number' ? [] : {}), path.slice(1), v); return c; };
const statusAr = (s: string) => (s === 'approved' ? 'معتمَد' : s === 'submitted' ? 'بانتظار الاعتماد' : s === 'returned' ? 'أُعيد' : 'مسودّة');
const CSS = `
.dr-map{display:flex;gap:.3rem;flex-wrap:wrap;margin:.2rem 0}.dr-map a,.dr-map span{display:inline-flex;align-items:center;gap:.25rem;font-size:.8rem;font-weight:800;padding:.15rem .55rem;border-radius:999px;border:1px solid #e5e8ef;background:#f7f8fb;color:#334155;text-decoration:none}.dr-map [data-state="closed"]{background:#d1fae5;border-color:#6ee7b7;color:#065f46}.dr-map [data-state="current"]{background:#fff7e6;border-color:#c9a24b;color:#7c5a10}
.dr-cardl li[data-current="1"]{border-color:#c9a24b}.dr-att{background:#ffedd5;color:#9a3412;border-radius:999px;padding:.1rem .5rem;font-size:.78rem;font-weight:800}
.dr-mu{display:flex;flex-wrap:wrap;gap:4px;align-items:center;font-size:12px}.dr-mu-k{font-weight:800;color:#475569;margin-inline-end:4px}.dr-mu select{font:inherit;font-size:12px;padding:1px 4px;border:1px solid #e2e8f0;border-radius:6px}.dr-mu-c{display:inline-flex;align-items:center;gap:4px;border:1px solid #e2e8f0;border-radius:999px;padding:2px 8px;background:#fff;cursor:pointer}.dr-mu-c.on{background:#ecfdf5;border-color:#6ee7b7}.dr-mu-c input{margin:0}.dr-mu-c b{font-family:ui-monospace,monospace;font-size:11px}
.dr-units{border-top:1px dashed #e5e8ef;margin-top:.4rem;padding-top:.5rem;display:grid;gap:.4rem}.dr-unit{display:grid;grid-template-columns:28px 1fr;gap:.4rem;align-items:start;border:1px solid #e5e8ef;border-radius:10px;padding:.45rem;background:#fff}.dr-unit[data-closed="1"]{background:#f0fdf9}.dr-unit b{color:#0f2a4e;text-align:center;padding-top:.4rem}.dr-unit .g{display:grid;gap:.3rem;grid-template-columns:2fr 1fr 1fr;min-width:0}.dr-unit .g .w{grid-column:1/-1}.dr-unit .g input{min-width:0}.dr-sk{display:flex;gap:.3rem;flex-wrap:wrap;grid-column:1/-1}.dr-sk label{font-size:.78rem;font-weight:700;display:inline-flex;gap:.2rem;align-items:center;border:1px solid #e5e8ef;border-radius:999px;padding:.1rem .45rem;background:#f7f8fb}.dr-sk input{width:auto}.dr-unit .mv{display:flex;gap:.25rem;grid-column:1/-1;justify-content:flex-end}
.dr-pulse{max-width:860px}.dr-pulse textarea{min-height:70px}.dr-follow{display:grid;grid-template-columns:1fr 160px 1fr;gap:.4rem;align-items:center;margin:.3rem 0}.dr-follow .nm{font-weight:800;color:#0f2a4e}.dr-follow .nm small{display:block;color:#64748b;font-weight:400}
.dr-grid .mk{font-size:.75rem;color:#0b6f69;white-space:nowrap;font-weight:800}.dr-grid td select{min-width:120px}.dr-grid td input[type=number]{width:70px;min-width:0}
.dr-strip{margin:1rem 0}.dr-strip h2{font-size:1.05rem;color:#0f2a4e;margin:0 0 .4rem;display:flex;gap:.4rem;align-items:center}.dr-strip ol{list-style:none;margin:0;padding:0;display:grid;gap:.35rem;grid-template-columns:repeat(auto-fit,minmax(220px,1fr))}.dr-strip li{border:1px solid #e5e8ef;border-radius:12px;padding:.5rem .7rem;background:#fff;min-width:0}.dr-strip li[data-state="closed"]{background:#f0fdf9;border-color:#6ee7b7}.dr-strip li[data-state="current"]{border-color:#c9a24b;background:#fffaf0}.dr-strip li b{color:#0f2a4e;display:block}.dr-strip li small{color:#64748b;display:block}.dr-strip li p{margin:.2rem 0 0;color:#334155;font-size:.9rem}
@media (max-width:720px){.dr-follow{grid-template-columns:1fr}.dr-unit .g{grid-template-columns:1fr}}
`;

/** ر4-ب: تُعيد «كشف الكفايات» استعمال الرأس والقرار والملاحظات والأنماط نفسها */
export { api as drApi, CSS as DR_CSS, statusAr as drStatusAr };
export const DrHead = (p: any) => <Head {...p} />; export const DrReturn = (p: any) => <Return {...p} />; export const DrNotes = (p: any) => <Notes {...p} />;

/* ───────── 1) بطاقات ملف الدبلوم ───────── */
export function DiplomaCards({ diploma, token }: { diploma: DiplomaCard[]; token: Tok }) {
  const [busy, setBusy] = useState(''); const [err, setErr] = useState(''); const [open, setOpen] = useState<string>(''); const [openP, setOpenP] = useState<string>(''); const [cards, setCards] = useState<DiplomaCard[]>(diploma);
  useEffect(() => setCards(diploma), [diploma]);
  if (!cards || !cards.length) return null;
  async function go(action: string, c: DiplomaCard, extra: any = {}, tid = '') { setBusy(tid || action + c.program_id + (c.classroom_id || '')); setErr(''); const j = await api(token, '/api/reports', { action, program_id: c.program_id, classroom_id: c.classroom_id, ...extra }); setBusy(''); if (!j.success) { setErr(j.error || 'فشل'); return; } window.location.href = `/me/reports/${j.report.id}`; }
  return <section className="pt-box mr mr-cards" aria-labelledby="dr-cards-h" data-testid="dr-cards" id="diploma"><style dangerouslySetInnerHTML={{ __html: MR_CSS + CSS }} />
    <h2 id="dr-cards-h"><Icon name="book" size={18} /> {R4_NAMES_AR.file} <small className="mr-story">«{R4_NAMES_AR.story}»</small></h2>
    <p className="pt-muted">الدبلوم طويل فلا يُختصر في تقرير؛ هو ملف يتراكم: <b>{R4_NAMES_AR.pulse}</b> نصف صفحة كل أسبوع، و<b>{R4_NAMES_AR.unit}</b> عند إغلاق كل وحدة — واعتماده هو الإغلاق. شعاره «{R4_NAMES_AR.motto}».</p>
    {err && <p className="mr-err" role="alert">{err}</p>}
    <ul className="mr-cardl dr-cardl">{cards.map(c => { const k = c.program_id + '|' + (c.classroom_id || ''); const cur = c.units.find(u => u.state === 'current'); return <li key={k} data-testid="dr-card" data-current={cur ? '1' : '0'}>
      <div className="mr-cardh"><b>{c.program_ar}</b><span>{c.classroom_ar}{c.level ? ` · ${c.level}` : ''}</span></div>
      <div className="mr-kpis"><span><b>{c.units.filter(u => u.state === 'closed').length}</b>/{c.units.length} <small>وحدات مغلقة</small></span><span className="b"><b>{c.week.week_no}</b> <small>الأسبوع · {fmtDayAr(c.week.from)} → {fmtDayAr(c.week.to)}</small></span>{c.attention_open > 0 && <span className="o" data-testid="dr-attention"><b>{c.attention_open}</b> <small>في {R4_NAMES_AR.attention}</small></span>}</div>
      {c.units.length ? <div className="dr-map" data-testid="dr-map" aria-label={R4_NAMES_AR.map}>{c.units.map(u => u.report_id ? <Link key={u.unit.idx} href={`/me/reports/${u.report_id}`} data-state={u.state} title={`${u.unit.title_ar} — ${statusAr(u.report_status || 'draft')}`}>{STATE_MARK[u.state]} {u.unit.idx}</Link> : <span key={u.unit.idx} data-state={u.state} title={`${u.unit.title_ar} — ${UNIT_STATE_AR[u.state]}`}>{STATE_MARK[u.state]} {u.unit.idx}</span>)}</div> : <p className="pt-muted" data-testid="dr-nounits">لا وحدات بعد — اكتبها أو استوردها من التصميم.</p>}
      <div className="mr-cardf">
        {c.pulse ? <Link className="pt-btn navy small" href={`/me/reports/${c.pulse.id}`} data-testid="dr-open-pulse">افتح {R4_NAMES_AR.pulse} · {statusAr(c.pulse.status)}</Link> : <button type="button" className="pt-btn gold small" onClick={() => go('create_pulse', c, { period_from: c.week.from }, 'pulse' + k)} disabled={!!busy} data-testid="dr-pulse">{busy === 'pulse' + k ? '…' : R4_NAMES_AR.pulse_start}</button>}
        {c.weekly?.id ? <Link className="pt-btn ghost small" href={`/me/reports/${c.weekly.id}`} data-testid="dr-open-weekly">{P46_NAMES_AR.weekly} · {statusAr(c.weekly.status)}</Link> : !c.weekly && <button type="button" className="pt-btn ghost small" onClick={() => go('create', c, { period_from: c.week.from, period_to: c.week.to }, 'full' + k)} disabled={!!busy} data-testid="dr-full">{R4_NAMES_AR.full_week}</button>}
        {cur && (cur.report_id ? <Link className="pt-btn ghost small" href={`/me/reports/${cur.report_id}`} data-testid="dr-open-unit">{R4_NAMES_AR.unit} {cur.unit.idx} · {statusAr(cur.report_status || 'draft')}</Link> : <button type="button" className="pt-btn ghost small" onClick={() => go('create_unit', c, { unit_id: cur.unit.id }, 'unit' + k)} disabled={!!busy} data-testid="dr-close-unit">{busy === 'unit' + k ? '…' : `${R4_NAMES_AR.close_unit} (${cur.unit.idx})`}</button>)}
        {c.can_edit_units && <button type="button" className="mr-linkbtn" onClick={() => setOpen(o => (o === k ? '' : k))} data-testid="dr-units-toggle">{open === k ? 'أخفِ الوحدات' : R4_NAMES_AR.units}</button>}
        <button type="button" className="mr-linkbtn" onClick={() => setOpenP(o => (o === k ? '' : k))} data-testid="dp-toggle">{openP === k ? 'أخفِ الكشوف' : R4_NAMES_AR.profile}</button>
      </div>
      {openP === k && <ProfilesPanel programId={c.program_id} classroomId={c.classroom_id} token={token} />}
      {open === k && <UnitsPanel programId={c.program_id} token={token} onSaved={us => setCards(cs => cs.map(x => (x.program_id === c.program_id ? { ...x, units: us.map((u, i) => ({ unit: u, state: u.closed_at ? 'closed' : (x.units.find(y => y.unit.id === u.id)?.state || (i === us.findIndex(z => !z.closed_at) ? 'current' : 'upcoming')), report_id: x.units.find(y => y.unit.id === u.id)?.report_id || null, report_status: x.units.find(y => y.unit.id === u.id)?.report_status || null })) } : x)))} />}
    </li>; })}</ul>
  </section>;
}

/* ───────── 2) وحدات الدبلوم ───────── */
export function UnitsPanel({ programId, token, onSaved }: { programId: string; token: Tok; onSaved?: (units: Unit[]) => void }) {
  const [units, setUnits] = useState<Unit[] | null>(null); const [skills, setSkills] = useState<{ code: string; name_ar: string }[]>([]); const [err, setErr] = useState(''); const [ok, setOk] = useState(''); const [busy, setBusy] = useState(''); const [dirty, setDirty] = useState(false);
  const [mu, setMu] = useState<{ code: string; level: string; title_ar: string }[]>([]); const [muLevel, setMuLevel] = useState(''); /* م6-ج: وحدات المستوى (خريطة المنهج) */
  const load = useCallback(async () => { const j = await api(token, `/api/reports?units=${encodeURIComponent(programId)}`); if (!j?.success) { setErr(j?.error || 'تعذّر التحميل'); return; } setUnits(j.units || []); setSkills(j.skills || []); const m = Array.isArray(j.miaar_units) ? j.miaar_units : []; setMu(m); setMuLevel(l => l || (m[0]?.level || '')); setDirty(false); }, [token, programId]);
  useEffect(() => { load(); }, [load]);
  const set = (i: number, k: keyof Unit, v: any) => { setUnits(us => (us ? us.map((u, j) => (j === i ? { ...u, [k]: v } : u)) : us)); setDirty(true); };
  const move = (i: number, d: number) => { setUnits(us => { if (!us) return us; const j = i + d; if (j < 0 || j >= us.length) return us; const a = [...us]; [a[i], a[j]] = [a[j], a[i]]; return a.map((u, n) => ({ ...u, idx: n + 1 })); }); setDirty(true); };
  async function save() { if (!units) return; setBusy('save'); setErr(''); setOk(''); const j = await api(token, '/api/reports', { action: 'units_save', program_id: programId, units }); setBusy(''); if (!j.success) { setErr(j.error || 'فشل الحفظ'); return; } setUnits(j.units); setDirty(false); setOk('حُفظت الوحدات'); onSaved?.(j.units); }
  async function imp() { setBusy('import'); setErr(''); setOk(''); const j = await api(token, '/api/reports', { action: 'units_import', program_id: programId }); setBusy(''); if (!j.success) { setErr(j.error || 'فشل الاستيراد'); return; } setUnits(j.units); setDirty(false); setOk(`استُوردت ${j.imported} وحدات من التصميم`); onSaved?.(j.units); }
  if (!units) return <div className="dr-units"><p className="pt-muted">{err || '…'}</p></div>;
  return <div className="dr-units" data-testid="dr-units">
    <p className="pt-muted" style={{ margin: 0 }}>الوحدة هي وحدة الحكم الحقيقية: عنوان، ناتج، ساعات، مهارات من قالب البرنامج، ومدّة. المغلقة بتقرير معتمَد لا تُحذف.</p>
    {units.map((u, i) => <div key={u.id || 'n' + i} className="dr-unit" data-testid="dr-unit" data-closed={u.closed_at ? '1' : '0'}><b>{i + 1}</b><div className="g">
      <input className="w" value={u.title_ar} onChange={e => set(i, 'title_ar', e.target.value.slice(0, UNIT_TITLE_MAX))} placeholder="عنوان الوحدة" readOnly={!!u.closed_at} aria-label={`عنوان الوحدة ${i + 1}`} />
      <input className="w" value={u.outcome_ar} onChange={e => set(i, 'outcome_ar', e.target.value.slice(0, UNIT_OUTCOME_MAX))} placeholder="ناتج الوحدة: ماذا يستطيع المتدرّب بعدها؟" readOnly={!!u.closed_at} aria-label={`ناتج الوحدة ${i + 1}`} />
      <input type="number" min={0} max={999} value={u.hours || ''} onChange={e => set(i, 'hours', Number(e.target.value) || 0)} placeholder="ساعات" aria-label="الساعات" /><input type="date" value={u.starts_on || ''} onChange={e => set(i, 'starts_on', e.target.value || null)} aria-label="من" /><input type="date" value={u.ends_on || ''} onChange={e => set(i, 'ends_on', e.target.value || null)} aria-label="إلى" />
      {mu.length > 0 && <div className="dr-mu" data-testid="dr-mu"><span className="dr-mu-k">خريطة المنهج</span>
        <select value={muLevel} onChange={e => setMuLevel(e.target.value)} aria-label="مستوى وحدات المستوى">{Array.from(new Set(mu.map(x => x.level))).map(l => <option key={l} value={l}>{l}</option>)}</select>
        {mu.filter(x => x.level === muLevel).map(x => { const on = (u.miaar_unit_codes || []).includes(x.code); return <label key={x.code} className={`dr-mu-c${on ? ' on' : ''}`} title={x.title_ar}><input type="checkbox" checked={on} disabled={!!u.closed_at} onChange={e => set(i, 'miaar_unit_codes', e.target.checked ? [...(u.miaar_unit_codes || []), x.code] : (u.miaar_unit_codes || []).filter(c => c !== x.code))} /><b dir="ltr">{x.code}</b> {x.title_ar}</label>; })}
        {(u.miaar_unit_codes || []).filter(c => !mu.some(x => x.code === c && x.level === muLevel)).map(c => <span key={c} className="dr-mu-c on" dir="ltr">{c}</span>)}
      </div>}
      {skills.length > 0 && <div className="dr-sk">{skills.map(s => <label key={s.code}><input type="checkbox" checked={u.skill_codes.includes(s.code)} onChange={e => set(i, 'skill_codes', e.target.checked ? [...u.skill_codes, s.code] : u.skill_codes.filter(c => c !== s.code))} disabled={!!u.closed_at} /> {s.name_ar}</label>)}</div>}
      <div className="mv">{u.closed_at ? <span className="mr-chip t">مغلقة ✓</span> : <><button type="button" className="pt-btn ghost small" onClick={() => move(i, -1)} disabled={i === 0} aria-label="أعلى">↑</button><button type="button" className="pt-btn ghost small" onClick={() => move(i, 1)} disabled={i === units.length - 1} aria-label="أسفل">↓</button><button type="button" className="mr-x" aria-label="حذف الوحدة" onClick={() => { setUnits(us => (us ? us.filter((_, j) => j !== i).map((x, n) => ({ ...x, idx: n + 1 })) : us)); setDirty(true); }}>×</button></>}</div>
    </div></div>)}
    <div className="mr-cardf">
      {units.length < UNIT_MAX && <button type="button" className="pt-btn ghost small" onClick={() => { setUnits(us => [...(us || []), { id: null, idx: (us?.length || 0) + 1, title_ar: '', outcome_ar: '', hours: 0, skill_codes: [], miaar_unit_codes: [], starts_on: null, ends_on: null, closed_at: null, source: 'manual' }]); setDirty(true); }} data-testid="dr-unit-add"><Icon name="plus" size={14} /> أضف وحدة</button>}
      {units.length === 0 && <button type="button" className="pt-btn ghost small" onClick={imp} disabled={!!busy} data-testid="dr-units-import"><Icon name="download" size={14} /> {busy === 'import' ? '…' : R4_NAMES_AR.import_design}</button>}
      <button type="button" className="pt-btn navy small" onClick={save} disabled={!!busy || !dirty} data-testid="dr-units-save"><Icon name="save" size={14} /> {busy === 'save' ? '…' : dirty ? 'احفظ الوحدات' : 'محفوظ'}</button>
      {err && <span className="mr-err" role="alert">{err}</span>}{ok && <span className="mr-ok" role="status">{ok}</span>}
    </div>
  </div>;
}

/* ───────── 3) نبض الأسبوع ───────── */
function Head({ r, c, kicker, title, sub, mode, onBack, busy, dirty, editable, act, save, print, extra }: any) {
  return <section className="pt-box mr-head">
    <div className="mr-head-top">
      <div><span className="pt-kicker"><Icon name="book" size={14} /> {kicker} · «{R4_NAMES_AR.story}»</span>{mode === 'admin' ? <h2 className="mr-h">{title}</h2> : <h1>{title}</h1>}<p className="pt-muted">{sub} · <span className={`mr-chip ${TONE[r.status]}`} data-testid="dr-status">{statusAr(r.status)}</span></p></div>
      <div className="mr-actions">
        {onBack ? <button className="pt-btn ghost small" type="button" onClick={onBack}><Icon name="arrow" size={14} /> القائمة</button> : <Link className="pt-btn ghost small" href="/me/reports#diploma"><Icon name="arrow" size={14} /> {R4_NAMES_AR.file}</Link>}
        {print && <button className="pt-btn ghost small" type="button" onClick={print} data-testid="dr-print"><Icon name="print" size={14} /> معاينة الطباعة</button>}
        {editable && <button className="pt-btn ghost small" type="button" onClick={() => act('recompute')} disabled={!!busy} data-testid="dr-recompute"><Icon name="refresh" size={14} /> {P46_NAMES_AR.recompute}</button>}
        {editable && <button className="pt-btn navy small" type="button" onClick={() => save()} disabled={!!busy || !dirty} data-testid="dr-save"><Icon name="save" size={14} /> {busy === 'save' ? '…' : dirty ? 'احفظ' : 'محفوظ'}</button>}
        {editable && mode === 'author' && <button className="pt-btn gold small" type="button" onClick={() => act('submit')} disabled={!!busy} data-testid="dr-submit"><Icon name="send" size={14} /> {P46_NAMES_AR.submit}</button>}
        {r.can_decide && <button className="pt-btn gold small" type="button" onClick={() => act('approve')} disabled={!!busy} data-testid="dr-approve"><Icon name="check" size={14} /> {P46_NAMES_AR.approve}</button>}
      </div>
    </div>
    {extra}
  </section>;
}
function Return({ r, busy, act }: any) { const [note, setNote] = useState(''); if (!r.can_decide) return null; return <div className="mr-return"><input value={note} onChange={e => setNote(e.target.value.slice(0, 400))} placeholder="ملاحظة الإعادة للمعلّم…" data-testid="dr-return-note" /><button className="pt-btn ghost small" type="button" onClick={() => act('return', { note })} disabled={!!busy || note.trim().length < 3} data-testid="dr-return"><Icon name="arrow" size={14} /> {P46_NAMES_AR.return}</button></div>; }
function Notes({ r, err, ok }: any) { return <>{r.status === 'returned' && r.return_note && <p className="mr-retbox" data-testid="dr-retnote">أُعيد بملاحظة: {r.return_note}</p>}{r.status === 'approved' && <p className="mr-okbox" data-testid="dr-okbox">معتمَد · رمز التحقّق <b>{r.verify_code}</b> · <Link href={`/verify/report/${r.verify_code}`}>صفحة التحقّق</Link></p>}{r.missing?.length > 0 && r.status !== 'approved' && <p className="mr-missing" data-testid="dr-missing">قبل الإرسال: {r.missing.join(' · ')}</p>}{err && <p className="mr-err" role="alert">{err}</p>}{ok && <p className="mr-ok" role="status" data-testid="dr-ok">{ok}</p>}</>; }

export function PulseEditor({ id, token, mode = 'author', onBack }: { id: string; token: Tok; mode?: 'author' | 'admin'; onBack?: () => void }) {
  const [d, setD] = useState<any>(null); const [err, setErr] = useState(''); const [ok, setOk] = useState(''); const [busy, setBusy] = useState(''); const [dirty, setDirty] = useState(false); const [body, setBody] = useState<PulseBody | null>(null); const [pick, setPick] = useState('');
  const load = useCallback(async () => { const j = await api(token, `/api/reports?id=${encodeURIComponent(id)}`); if (!j?.success) { setErr(j?.error || 'تعذّر التحميل'); return; } setD(j); setBody(j.report.body); setDirty(false); }, [token, id]);
  useEffect(() => { load(); }, [load]);
  useEffect(() => { const h = (e: BeforeUnloadEvent) => { if (dirty) { e.preventDefault(); e.returnValue = ''; } }; window.addEventListener('beforeunload', h); return () => window.removeEventListener('beforeunload', h); }, [dirty]);
  const r = d?.report; const c: PulseComputed | null = r?.computed || null; const editable = !!r?.can_edit; const ro = !editable;
  const setB = (path: (string | number)[], v: any) => { setBody(b => (b ? upd(b, path, v) : b)); setDirty(true); };
  async function save(silent = false): Promise<boolean> { if (!body) return false; setBusy('save'); setErr(''); if (!silent) setOk(''); const j = await api(token, '/api/reports', { action: 'save', id, body }); setBusy(''); if (!j.success) { setErr(j.error || 'فشل الحفظ'); return false; } setD((x: any) => ({ ...x, report: j.report })); setBody(j.report.body); setDirty(false); if (!silent) setOk('حُفظ'); return true; }
  async function act(action: string, extra: any = {}) { setBusy(action); setErr(''); setOk(''); if (dirty && ['submit', 'recompute'].includes(action)) { const s = await save(true); if (!s) { setBusy(''); return; } } const j = await api(token, '/api/reports', { action, id, ...extra }); setBusy(''); if (!j.success) { setErr(j.error || 'فشل'); return; } await load(); setOk(action === 'submit' ? 'أُرسل — بانتظار اعتماد الطاقم' : action === 'approve' ? `اعتُمد — رمز التحقّق ${j.verify_code}` : action === 'return' ? 'أُعيد بملاحظة' : 'حُدِّثت الأرقام'); }
  if (!d || !body || !c) return <main className="pt-main mr dr-pulse"><style dangerouslySetInnerHTML={{ __html: MR_CSS + CSS }} /><section className="pt-box"><p className="pt-muted">{err || '…'}</p></section></main>;
  const free = c.roster.filter(x => !body.attention.some(a => a.key === x.key) && !body.follow.some(f => f.key === x.key));
  return <main className="pt-main mr dr-pulse" data-testid="dr-pulse-editor" data-status={r.status}><style dangerouslySetInnerHTML={{ __html: MR_CSS + CSS }} />
    <Head r={r} c={c} mode={mode} onBack={onBack} busy={busy} dirty={dirty} editable={editable} act={act} save={save} kicker={R4_NAMES_AR.pulse} title={`${R4_NAMES_AR.pulse} ${c.week_no} — ${c.program_ar}`} sub={`${c.classroom_ar || ''}${c.unit ? ` · الوحدة ${c.unit.idx} «${c.unit.title_ar}»` : ''} · ${fmtDayAr(c.period_from)} → ${fmtDayAr(c.period_to)}`}
      extra={<><Return r={r} busy={busy} act={act} /><Notes r={r} err={err} ok={ok} />
        <div className="mr-kpis" data-testid="dr-kpis"><span><b>{c.sessions}</b> <small>جلسات</small></span><span><b>{c.hours}</b> <small>ساعات</small></span><span><b>{c.enrolled}</b> <small>مقيَّدون</small></span><span className={c.absent ? 'o' : ''}><b>{c.absent}</b> <small>غابوا الأسبوع كلّه</small></span><span className="b"><b>{c.around.missions}</b> <small>مهمات</small></span><span className="b"><b>{c.around.rehearsals}</b> <small>بروفات</small></span><span className="b"><b>{c.around.cases}</b> <small>«كل يوم مهارة»</small></span><span><b>{c.units_closed}</b>/{c.units_total} <small>وحدات مغلقة</small></span></div>
        {c.full_weekly_id ? <p className="pt-muted">لهذا الأسبوع تقرير أسبوعي كامل أيضًا — <Link href={`/me/reports/${c.full_weekly_id}`}>افتحه</Link>.</p> : null}
      </>} />
    <section className="pt-box mr-sec"><h2>١ · ما تمّ هذا الأسبوع</h2><textarea value={body.done} onChange={e => setB(['done'], e.target.value.slice(0, PULSE_TEXT_MAX))} placeholder="سطران: ما الذي قُدِّم وما الذي لمسته…" maxLength={PULSE_TEXT_MAX} readOnly={ro} data-testid="dr-done" /></section>
    {body.follow.length > 0 && <section className="pt-box mr-sec" data-testid="dr-follow"><h2>٢ · {R4_NAMES_AR.attention} — ما الذي تغيّر؟</h2><p className="pt-muted">هؤلاء ذُكروا في نبض سابق. لا أحد يسقط بين الأسابيع: اختر لكل اسم ما آل إليه.</p>
      {body.follow.map((f, i) => <div key={f.key} className="dr-follow"><div className="nm">{f.name}<small>منذ الأسبوع {f.since_week} · {f.prev_reason}</small></div><select value={f.change} onChange={e => setB(['follow', i, 'change'], e.target.value)} disabled={ro} aria-label={`ما الذي تغيّر — ${f.name}`} data-testid="dr-follow-change"><option value="">— اختر —</option>{ATTENTION_CHANGE.map(x => <option key={x} value={x}>{ATTENTION_CHANGE_AR[x]}</option>)}</select><input value={f.note} onChange={e => setB(['follow', i, 'note'], e.target.value.slice(0, SHORT_MAX))} placeholder="ملاحظة قصيرة (اختياري)" readOnly={ro} /></div>)}</section>}
    <section className="pt-box mr-sec" data-testid="dr-attention-sec"><h2>{body.follow.length ? '٣' : '٢'} · من يحتاج انتباهًا هذا الأسبوع؟</h2>
      {body.attention.map((a, i) => <div key={a.key} className="mr-li"><span className="dr-follow nm" style={{ minWidth: 160 }}>{a.name}</span><input value={a.reason} onChange={e => setB(['attention', i, 'reason'], e.target.value.slice(0, SHORT_MAX))} placeholder="السبب بكلمات" readOnly={ro} data-testid="dr-att-reason" />{editable && <button type="button" className="mr-x" aria-label="حذف" onClick={() => setB(['attention'], body.attention.filter((_, j) => j !== i))}>×</button>}</div>)}
      {editable && body.attention.length < PULSE_MAX_ATTENTION && free.length > 0 && <div className="mr-row"><select value={pick} onChange={e => setPick(e.target.value)} aria-label="اختر متدرّبًا" data-testid="dr-att-pick"><option value="">— اختر اسمًا —</option>{free.map(x => <option key={x.key} value={x.key}>{x.name}</option>)}</select><button type="button" className="pt-btn ghost small" disabled={!pick} onClick={() => { const x = c.roster.find(y => y.key === pick); if (x) { setB(['attention'], [...body.attention, { key: x.key, name: x.name, reason: '' }]); setPick(''); } }} data-testid="dr-att-add"><Icon name="plus" size={14} /> أضف</button></div>}
      {!body.attention.length && <p className="pt-muted">لا أحد — وهذا خبر جيّد يُوثَّق أيضًا.</p>}
    </section>
    <section className="pt-box mr-sec"><h2>{body.follow.length ? '٤' : '٣'} · ما يلزمنا</h2><textarea value={body.need} onChange={e => setB(['need'], e.target.value.slice(0, PULSE_TEXT_MAX))} placeholder="طلب للإدارة أو للزملاء — أو «لا شيء»" maxLength={PULSE_TEXT_MAX} readOnly={ro} data-testid="dr-need" /></section>
  </main>;
}

/* ───────── 4) تقرير الوحدة ───────── */
const SECS = ['بيانات الوحدة', 'التنفيذ', 'التقييم', 'كشف الوحدة', R4_NAMES_AR.attention, 'ما بعد الوحدة', 'الاعتماد'];
export function UnitEditor({ id, token, mode = 'author', onBack }: { id: string; token: Tok; mode?: 'author' | 'admin'; onBack?: () => void }) {
  const [d, setD] = useState<any>(null); const [err, setErr] = useState(''); const [ok, setOk] = useState(''); const [busy, setBusy] = useState(''); const [dirty, setDirty] = useState(false); const [body, setBody] = useState<UnitBody | null>(null); const [students, setStudents] = useState<UnitStudent[]>([]); const [lines, setLines] = useState<Record<string, string>>({}); const [linesOk, setLinesOk] = useState(false); const [sec, setSec] = useState(1); const [print, setPrint] = useState(false); const [phr, setPhr] = useState<{ phrases: Phrase[]; note_ar: string } | null>(null); const [pick, setPick] = useState('');
  const load = useCallback(async () => { const j = await api(token, `/api/reports?id=${encodeURIComponent(id)}`); if (!j?.success) { setErr(j?.error || 'تعذّر التحميل'); return; } setD(j); setBody(j.report.body); setStudents(j.report.students || []); setLines(Object.fromEntries(((j.report.lines || []) as any[]).map((l: any) => [l.key, l.text]))); setLinesOk(!!j.report.lines_ok); setDirty(false); }, [token, id]);
  useEffect(() => { load(); }, [load]);
  useEffect(() => { const h = (e: BeforeUnloadEvent) => { if (dirty) { e.preventDefault(); e.returnValue = ''; } }; window.addEventListener('beforeunload', h); return () => window.removeEventListener('beforeunload', h); }, [dirty]);
  const r = d?.report; const c: UnitComputed | null = r?.computed || null; const skills = c?.unit_skills || c?.skills || []; const editable = !!r?.can_edit; const ro = !editable;
  const setB = (path: (string | number)[], v: any) => { setBody(b => (b ? upd(b, path, v) : b)); setDirty(true); };
  const setScore = (key: string, code: string, v: string) => { setStudents(ss => ss.map(s => (s.key === key ? { ...s, scores: { ...s.scores, [code]: v === '' ? null : Math.max(0, Math.min(100, Number(v))) } } : s))); setDirty(true); };
  const setStu = (key: string, k: 'note' | 'decision', v: string) => { setStudents(ss => ss.map(s => (s.key === key ? { ...s, [k]: v } : s))); setDirty(true); };
  const live = useMemo(() => students.map(s => { const vals = skills.map(k => s.scores?.[k.code]).filter((v): v is number => v !== null && v !== undefined && Number.isFinite(v)); const avg = vals.length ? Math.round((vals.reduce((a, b) => a + b, 0) / vals.length) * 10) / 10 : null; const g = avg === null ? null : avg >= 90 ? 'ممتاز' : avg >= 80 ? 'جيد جدًا' : avg >= 70 ? 'جيد' : avg >= 60 ? 'مقبول' : 'ضعيف'; return { ...s, avg, grade_ar: g }; }), [students, skills]);
  const stats = useMemo(() => summativeStats(live), [live]); const suggested = useMemo(() => outcomePctSuggested(live), [live]);
  async function save(silent = false): Promise<boolean> { if (!body) return false; setBusy('save'); setErr(''); if (!silent) setOk(''); const j = await api(token, '/api/reports', { action: 'save', id, body, students: live, lines: Object.entries(lines).map(([key, text]) => ({ key, text })), lines_ok: linesOk }); setBusy(''); if (!j.success) { setErr(j.error || 'فشل الحفظ'); return false; } setD((x: any) => ({ ...x, report: j.report })); setBody(j.report.body); setStudents(j.report.students || []); setDirty(false); if (!silent) setOk('حُفظ'); return true; }
  async function act(action: string, extra: any = {}) { setBusy(action); setErr(''); setOk(''); if (dirty && ['submit', 'recompute'].includes(action)) { const s = await save(true); if (!s) { setBusy(''); return; } } const j = await api(token, '/api/reports', { action, id, ...extra }); setBusy(''); if (!j.success) { setErr(j.error || 'فشل'); return; } await load(); setOk(action === 'submit' ? 'أُرسل — بانتظار اعتماد الطاقم' : action === 'approve' ? `اعتُمد — رمز التحقّق ${j.verify_code} · أُغلقت الوحدة` : action === 'return' ? 'أُعيد بملاحظة' : 'حُدِّثت الأرقام والشواهد من أَثَر'); }
  async function phrase() { setBusy('phrase'); setErr(''); const j = await api(token, '/api/reports', { action: 'phrase', id }); setBusy(''); if (!j.success) { setErr(j.error || 'فشل'); return; } setPhr({ phrases: j.phrases || [], note_ar: j.note_ar || '' }); }
  function adopt(p: Phrase) { if (!body) return; const add = (cur: string) => (cur ? cur + ' ' + p.text : p.text).slice(0, TEXT_MAX); if (p.section === 'strengths' || p.section === 'general_notes') setB(['outcome', 'judgment'], add(body.outcome.judgment)); else if (p.section === 'admin_attendance') setB(['next', 'admin'], add(body.next.admin)); else setB(['execution', 'notes'], add(body.execution.notes)); setPhr(x => (x ? { ...x, phrases: x.phrases.filter(y => y !== p) } : x)); }
  if (!d || !body || !c) return <main className="pt-main mr"><style dangerouslySetInnerHTML={{ __html: MR_CSS + CSS }} /><section className="pt-box"><p className="pt-muted">{err || '…'}</p></section></main>;
  if (print) return <UnitDoc r={{ ...r, body, students: live }} onClose={() => setPrint(false)} />;
  const ta = (path: (string | number)[], v: string, ph: string, tid?: string, max = TEXT_MAX) => <textarea value={v} onChange={e => setB(path, e.target.value.slice(0, max))} placeholder={ph} rows={3} maxLength={max} readOnly={ro} data-testid={tid} />;
  const u = c.unit;
  return <main className="pt-main mr mr-ed" data-testid="dr-unit-editor" data-status={r.status}><style dangerouslySetInnerHTML={{ __html: MR_CSS + CSS }} />
    <Head r={r} c={c} mode={mode} onBack={onBack} busy={busy} dirty={dirty} editable={editable} act={act} save={save} print={() => setPrint(true)} kicker={R4_NAMES_AR.unit} title={`الوحدة ${u.idx} «${u.title_ar}» — ${c.program_ar}`} sub={`${c.classroom_ar || ''} · ${fmtDayAr(c.period_from)} → ${fmtDayAr(c.period_to)} · ${c.trainer_ar}`}
      extra={<><Return r={r} busy={busy} act={act} /><Notes r={r} err={err} ok={ok} />
        <div className="mr-kpis" data-testid="dr-unit-kpis"><span><b>{c.sessions}</b> <small>جلسات</small></span><span><b>{c.hours}</b>{c.planned_hours ? <small>/{c.planned_hours} ساعة مخطَّطة</small> : <small> ساعات</small>}</span><span><b>{c.enrolled}</b> <small>مقيَّدون</small></span><span className="b"><b>{c.weekly_approved}</b> <small>أسبوعيات معتمَدة</small></span><span className="b"><b>{c.pulses_approved}</b> <small>نبضات</small></span><span><b>{c.around.missions}</b> <small>مهمات مصدَّقة</small></span><span><b>{c.around.rehearsals}</b> <small>بروفات</small></span><span><b>{u.idx}</b>/{c.units_total} <small>الوحدة</small></span></div>
        <div className="mr-secs" role="tablist" aria-label="أقسام التقرير">{SECS.map((s, i) => <button key={s} type="button" role="tab" aria-selected={sec === i + 1} className={sec === i + 1 ? 'on' : ''} onClick={() => setSec(i + 1)} data-testid={`dr-sec-${i + 1}`}>{i + 1}. {s}</button>)}</div>
      </>} />
    {sec === 1 && <section className="pt-box mr-sec" data-testid="dr-s1"><h2>١ · بيانات الوحدة (من أَثَر)</h2>
      <table className="mr-t"><tbody><tr><th>البرنامج</th><td>{c.program_ar}</td><th>الجهة</th><td>{c.org_ar || '—'}</td></tr><tr><th>الشعبة</th><td>{c.classroom_ar || '—'}</td><th>المعلّم</th><td>{c.trainer_ar}</td></tr><tr><th>الوحدة</th><td>{u.idx} من {c.units_total} — {u.title_ar}</td><th>الساعات</th><td>{c.hours} منفَّذة{c.planned_hours ? ` / ${c.planned_hours} مخطَّطة` : ''}</td></tr><tr><th>الفترة</th><td>{fmtDayAr(c.period_from)} → {fmtDayAr(c.period_to)}{c.planned_from ? <small> (مخطَّط: {fmtDayAr(c.planned_from)} → {c.planned_to ? fmtDayAr(c.planned_to) : '…'})</small> : null}</td><th>المهارات</th><td>{skills.map(s => s.name_ar).join(' · ') || '—'}</td></tr><tr><th>ناتج الوحدة</th><td colSpan={3}>{u.outcome_ar || '—'}</td></tr></tbody></table>
      <h3>أسابيع الوحدة</h3>{c.weeks.length ? <ul className="pr-ul">{c.weeks.map(w => <li key={w.id}>{w.kind === 'weekly' ? P46_NAMES_AR.weekly : R4_NAMES_AR.pulse} {w.week_no} · {fmtDayAr(w.period_from)} → {fmtDayAr(w.period_to)} · {statusAr(w.status)}{w.verify_code ? ` · ${w.verify_code}` : ''}</li>)}</ul> : <p className="pt-muted">لا أسبوعيات ولا نبضات داخل فترة الوحدة بعد.</p>}
      <p className="mr-key">كشف الوحدة {c.grid_source === 'weeks' ? 'عُبِّئ مبدئيًا من متوسط الأسبوعيات المعتمَدة داخل الوحدة — عدّله كما تشاء.' : 'فارغ لأن لا أسبوعيات معتمَدة داخل الوحدة — تكتبه بنفسك.'}</p>
    </section>}
    {sec === 2 && <section className="pt-box mr-sec" data-testid="dr-s2"><h2>٢ · التنفيذ</h2><label className="mr-lbl">ما انحرف عن الخطّة (ساعات، محتوى، ترتيب) ولماذا{ta(['execution', 'deviation'], body.execution.deviation, 'إن لم يكن انحراف فاكتب «نُفِّذت كما خُطِّط».', 'dr-deviation')}</label><label className="mr-lbl">ملاحظات التنفيذ{ta(['execution', 'notes'], body.execution.notes, 'ما نجح وما أعاق…', 'dr-exec-notes')}</label></section>}
    {sec === 3 && <section className="pt-box mr-sec" data-testid="dr-s3"><h2>٣ · التقييم</h2>
      <div className="mr-scroll"><table className="mr-t"><thead><tr><th>الأداة</th><th>المهارة</th><th>الوصف</th><th></th></tr></thead><tbody>{body.assessment.tools.map((t, i) => <tr key={i}><td><select value={UNIT_TOOLS_AR.includes(t.tool) ? t.tool : '__'} onChange={e => setB(['assessment', 'tools', i, 'tool'], e.target.value === '__' ? t.tool : e.target.value)} disabled={ro} aria-label="الأداة">{UNIT_TOOLS_AR.map(x => <option key={x} value={x}>{x}</option>)}<option value="__">أخرى…</option></select>{!UNIT_TOOLS_AR.includes(t.tool) && <input value={t.tool} onChange={e => setB(['assessment', 'tools', i, 'tool'], e.target.value.slice(0, SHORT_MAX))} placeholder="اسم الأداة" readOnly={ro} />}</td><td><select value={t.skill} onChange={e => setB(['assessment', 'tools', i, 'skill'], e.target.value)} disabled={ro} aria-label="المهارة"><option value="">كل المهارات</option>{skills.map(s => <option key={s.code} value={s.code}>{s.name_ar}</option>)}</select></td><td><input value={t.desc} onChange={e => setB(['assessment', 'tools', i, 'desc'], e.target.value.slice(0, TEXT_MAX))} placeholder="ماذا قيس وكيف" readOnly={ro} /></td><td>{editable && <button type="button" className="mr-x" aria-label="حذف" onClick={() => setB(['assessment', 'tools'], body.assessment.tools.filter((_, j) => j !== i))}>×</button>}</td></tr>)}</tbody></table></div>
      {editable && body.assessment.tools.length < 8 && <button type="button" className="pt-btn ghost small" onClick={() => setB(['assessment', 'tools'], [...body.assessment.tools, { tool: UNIT_TOOLS_AR[0], skill: '', desc: '' }])} data-testid="dr-tool-add"><Icon name="plus" size={14} /> أداة</button>}
      <label className="mr-lbl">ملاحظات التقييم{ta(['assessment', 'notes'], body.assessment.notes, 'اختياري', 'dr-assess-notes')}</label>
    </section>}
    {sec === 4 && <section className="pt-box mr-sec dr-grid" data-testid="dr-s4"><h2>٤ · كشف الوحدة — «{R4_NAMES_AR.motto}»</h2>
      <div className="mr-stats"><span>المتوسّط <b>{stats.avg ?? '—'}</b></span><span className="t">اجتازوا ({PASS_MARK}+) <b>{stats.pass_pct ?? '—'}%</b></span><span className="r">يحتاجون دعمًا <b>{stats.support_pct ?? '—'}%</b></span><span>مقيَّمون <b>{stats.n}</b></span><span>الشواهد: {Object.values(EVIDENCE_MARKS_AR).join(' · ')}</span></div>
      <div className="mr-scroll"><table className="mr-t"><thead><tr><th>#</th><th>المتدرّب</th><th>حضور</th>{skills.map(k => <th key={k.code}>{k.name_ar}</th>)}<th>المتوسّط</th><th>التقدير</th><th>الشواهد</th><th>قرار الوحدة</th><th>ملاحظة</th></tr></thead><tbody>
        {live.map((s, i) => <tr key={s.key} data-testid="dr-student"><td>{i + 1}</td><th>{s.name}</th><td>{s.attendance_pct === null ? '—' : `${s.attendance_pct}%`}</td>{skills.map(k => <td key={k.code}><input type="number" min={0} max={100} inputMode="numeric" value={s.scores?.[k.code] ?? ''} onChange={e => setScore(s.key, k.code, e.target.value)} readOnly={ro} aria-label={`${k.name_ar} — ${s.name}`} /></td>)}<td>{s.avg ?? '—'}</td><td>{s.grade_ar || '—'}</td><td className="mk" data-testid="dr-marks">{s.marks?.missions ? `م${s.marks.missions} ` : ''}{s.marks?.rehearsals ? `ب${s.marks.rehearsals} ` : ''}{s.marks?.cases ? `ي${s.marks.cases} ` : ''}{s.marks?.stations ? `ح${s.marks.stations}` : ''}{!s.marks?.missions && !s.marks?.rehearsals && !s.marks?.cases && !s.marks?.stations ? '—' : ''}</td><td><select value={s.decision || ''} onChange={e => setStu(s.key, 'decision', e.target.value)} disabled={ro} aria-label={`قرار — ${s.name}`} data-testid="dr-decision"><option value="">—</option>{UNIT_DECISION.map(x => <option key={x} value={x}>{UNIT_DECISION_AR[x]}</option>)}</select></td><td><input value={s.note || ''} onChange={e => setStu(s.key, 'note', e.target.value.slice(0, 160))} readOnly={ro} /></td></tr>)}
      </tbody></table></div>
      <p className="mr-key">مفتاح التقدير: {GRADE_KEY_AR}. الشواهد تُحسب من أَثَر خلال فترة الوحدة (مهمات مصدَّقة · بروفات · «كل يوم مهارة» · محطات) — لا تُكتب يدويًا.</p>
    </section>}
    {sec === 5 && <section className="pt-box mr-sec" data-testid="dr-s5"><h2>٥ · {R4_NAMES_AR.attention} خلال الوحدة</h2>
      {body.attention.length ? <div className="mr-scroll"><table className="mr-t"><thead><tr><th>المتدرّب</th><th>السبب</th><th>منذ</th><th>آخر حالة</th><th>القرار في نهاية الوحدة</th></tr></thead><tbody>{body.attention.map((a, i) => { const ca = c.attention.find(x => x.key === a.key); return <tr key={a.key}><th>{a.name}</th><td>{ca?.reason || '—'}</td><td>الأسبوع {ca?.since_week || '—'}</td><td>{ca?.last_change ? ATTENTION_CHANGE_AR[ca.last_change] : '—'}</td><td><input value={a.decision} onChange={e => setB(['attention', i, 'decision'], e.target.value.slice(0, SHORT_MAX))} placeholder="ما تقرّر" readOnly={ro} data-testid="dr-att-decision" /></td></tr>; })}</tbody></table></div> : <p className="pt-muted" data-testid="dr-att-empty">لم يُذكر أحد في نبضات هذه الوحدة.</p>}
    </section>}
    {sec === 6 && <section className="pt-box mr-sec" data-testid="dr-s6"><h2>٦ · ما تحقّق من ناتج الوحدة وما بعدها</h2>
      <label className="mr-lbl">الحكم على ناتج الوحدة «{u.outcome_ar || '—'}»{ta(['outcome', 'judgment'], body.outcome.judgment, 'هل بلغ أغلبهم الناتج؟ ما الدليل؟', 'dr-judgment')}</label>
      <div className="mr-row"><label>نسبة من بلغوا الناتج %<input type="number" min={0} max={100} value={body.outcome.pct ?? ''} onChange={e => setB(['outcome', 'pct'], e.target.value === '' ? null : Number(e.target.value))} readOnly={ro} style={{ width: 90, minWidth: 0, flex: 'none' }} data-testid="dr-pct" /></label>{suggested !== null && <span className="pt-muted">مقترَح من الكشف: {suggested}% {editable && body.outcome.pct !== suggested && <button type="button" className="mr-linkbtn" onClick={() => setB(['outcome', 'pct'], suggested)} data-testid="dr-pct-adopt">اعتمده</button>}</span>}</div>
      <label className="mr-lbl">الشاهد{ta(['outcome', 'evidence'], body.outcome.evidence, 'أعمال، مهمات، أداء مباشر…', 'dr-evidence')}</label>
      <h3>خطة دعم فردية</h3>{body.next.support.map((s, i) => <div key={s.key} className="mr-li2"><span><b>{s.name}</b></span><input value={s.what} onChange={e => setB(['next', 'support', i, 'what'], e.target.value.slice(0, TEXT_MAX))} placeholder="ما الدعم" readOnly={ro} /><input value={s.owner} onChange={e => setB(['next', 'support', i, 'owner'], e.target.value.slice(0, 80))} placeholder="من" readOnly={ro} style={{ maxWidth: 140 }} />{editable && <button type="button" className="mr-x" aria-label="حذف" onClick={() => setB(['next', 'support'], body.next.support.filter((_, j) => j !== i))}>×</button>}</div>)}
      {editable && body.next.support.length < MAX_LIST && <div className="mr-row"><select value={pick} onChange={e => setPick(e.target.value)} aria-label="اختر متدرّبًا" data-testid="dr-support-pick"><option value="">— اختر اسمًا —</option>{live.filter(s => !body.next.support.some(x => x.key === s.key)).map(s => <option key={s.key} value={s.key}>{s.name}{s.decision ? ` · ${UNIT_DECISION_AR[s.decision as keyof typeof UNIT_DECISION_AR]}` : ''}</option>)}</select><button type="button" className="pt-btn ghost small" disabled={!pick} onClick={() => { const s = live.find(x => x.key === pick); if (s) { setB(['next', 'support'], [...body.next.support, { key: s.key, name: s.name, what: '', owner: '' }]); setPick(''); } }} data-testid="dr-support-add"><Icon name="plus" size={14} /> أضف</button></div>}
      <label className="mr-lbl">ما يُعدَّل في الوحدة القادمة{ta(['next', 'adjust'], body.next.adjust, 'اختياري', 'dr-adjust')}</label>
      <label className="mr-lbl">ملاحظة إدارية{ta(['next', 'admin'], body.next.admin, 'اختياري', 'dr-admin')}</label>
      {editable && <div className="mr-ai"><div className="mr-cardf"><button type="button" className="pt-btn ghost small" onClick={phrase} disabled={!!busy} data-testid="dr-phrase"><Icon name="spark" size={14} /> {busy === 'phrase' ? '…' : 'اقترح صياغة من الأرقام'}</button><small className="pt-muted">الذكاء الاصطناعي يصوغ من الكشف فقط؛ الحكم لك.</small></div>{phr && <><p className="pt-muted" style={{ margin: 0 }}>{phr.note_ar}</p><ul className="mr-phr">{phr.phrases.map((p, i) => <li key={i}><span>{p.text}</span><button type="button" className="pt-btn ghost small" onClick={() => adopt(p)} data-testid="dr-adopt">أضف</button></li>)}</ul></>}</div>}
    </section>}
    {sec === 7 && <section className="pt-box mr-sec" data-testid="dr-s7"><h2>٧ · الاعتماد و«{R4_NAMES_AR.unit_line}»</h2>
      <p className="pt-muted">عند اعتماد الطاقم تُغلق الوحدة {u.idx} وتظهر ✓ في خريطة الوحدات، ويصل كل متدرّب سطرُه إن أذنت. المعلّم: {c.trainer_ar} · الكاتب: {r.author_name || r.author_email}.</p>
      <label className="mr-row" style={{ fontWeight: 700 }}><input type="checkbox" checked={linesOk} onChange={e => { setLinesOk(e.target.checked); setDirty(true); }} disabled={ro} style={{ width: 'auto' }} data-testid="dr-lines-ok" /> أرسل لكل متدرّب سطره الخاص بعد الاعتماد</label>
      {linesOk && <div className="mr-list">{live.map(s => <label key={s.key} className="mr-lbl">{s.name}<input value={lines[s.key] || ''} onChange={e => { setLines(l => ({ ...l, [s.key]: e.target.value.slice(0, LINE_MAX) })); setDirty(true); }} placeholder={`سطر لـ${s.name}: ما بلغه وما يليه…`} readOnly={ro} maxLength={LINE_MAX} data-testid="dr-line" /></label>)}</div>}
    </section>}
    <nav className="mr-nav" aria-label="تنقّل الأقسام"><button type="button" className="pt-btn ghost small" onClick={() => setSec(s => Math.max(1, s - 1))} disabled={sec === 1}>→ السابق</button><span>{sec} / {SECS.length}</span><button type="button" className="pt-btn ghost small" onClick={() => setSec(s => Math.min(SECS.length, s + 1))} disabled={sec === SECS.length}>التالي ←</button></nav>
  </main>;
}

/* ───────── 5) المطبوع ───────── */
export function UnitDoc({ r, onClose }: { r: any; onClose?: () => void }) {
  const c: UnitComputed = r.computed; const b: UnitBody = r.body; const st: UnitStudent[] = Array.isArray(r.students) ? r.students : []; const skills = c.unit_skills || c.skills || []; const u = c.unit; const stats = summativeStats(st);
  return <main className="pt-main pr" data-testid="dr-doc"><style dangerouslySetInnerHTML={{ __html: MR_CSS + MR_PRINT_CSS }} />
    <div className="pr-bar">{onClose && <button type="button" className="pt-btn ghost small" onClick={onClose}><Icon name="arrow" size={14} /> عودة للمحرّر</button>}<button type="button" className="pt-btn navy small" onClick={() => window.print()}><Icon name="print" size={14} /> اطبع / احفظ PDF</button><small>A4 · {R4_NAMES_AR.official}</small></div>
    <article className="pr-page">
      <header className="pr-head"><div><h1>{R4_NAMES_AR.unit} {u.idx} — {u.title_ar}</h1><p>{c.program_ar}{c.org_ar ? ` · ${c.org_ar}` : ''}{c.classroom_ar ? ` · ${c.classroom_ar}` : ''}</p><p>{fmtDayAr(c.period_from)} → {fmtDayAr(c.period_to)} · {c.sessions} جلسات · {c.hours} ساعة{c.planned_hours ? ` من ${c.planned_hours}` : ''}</p></div><div className="pr-meta"><span>المعلّم: {c.trainer_ar}</span><span>الوحدة {u.idx} من {c.units_total}</span>{r.verify_code && <span>رمز التحقّق: {r.verify_code}</span>}{r.approved_name && <span>اعتمده: {r.approved_name}</span>}</div></header>
      <h2>١ · ناتج الوحدة</h2><p className="pr-p">{u.outcome_ar || '—'}</p><p className="pr-key">المهارات: {skills.map(s => s.name_ar).join(' · ') || '—'} · أسابيع الوحدة: {c.weeks.length} ({c.weekly_approved} أسبوعية معتمَدة · {c.pulses_approved} نبض)</p>
      <h2>٢ · التنفيذ</h2><p className="pr-p">{b.execution.deviation || '—'}</p>{b.execution.notes && <p className="pr-p">{b.execution.notes}</p>}
      <h2>٣ · التقييم</h2>{b.assessment.tools.length ? <table><thead><tr><th>الأداة</th><th>المهارة</th><th>الوصف</th></tr></thead><tbody>{b.assessment.tools.map((t, i) => <tr key={i}><td>{t.tool}</td><td>{skills.find(s => s.code === t.skill)?.name_ar || 'الكلّ'}</td><td>{t.desc}</td></tr>)}</tbody></table> : <p className="pr-p">—</p>}
      <h2>٤ · كشف الوحدة</h2><table><thead><tr><th>#</th><th>المتدرّب</th><th>حضور</th>{skills.map(k => <th key={k.code}>{k.name_ar}</th>)}<th>المتوسّط</th><th>التقدير</th><th>الشواهد</th><th>القرار</th></tr></thead><tbody>{st.map((s, i) => <tr key={s.key}><td>{i + 1}</td><th>{s.name}</th><td>{s.attendance_pct === null ? '—' : `${s.attendance_pct}%`}</td>{skills.map(k => <td key={k.code}>{s.scores?.[k.code] ?? '—'}</td>)}<td>{s.avg ?? '—'}</td><td>{s.grade_ar || '—'}</td><td>{[s.marks?.missions ? `م${s.marks.missions}` : '', s.marks?.rehearsals ? `ب${s.marks.rehearsals}` : '', s.marks?.cases ? `ي${s.marks.cases}` : '', s.marks?.stations ? `ح${s.marks.stations}` : ''].filter(Boolean).join(' ') || '—'}</td><td>{s.decision ? UNIT_DECISION_AR[s.decision as keyof typeof UNIT_DECISION_AR] : '—'}</td></tr>)}</tbody></table>
      <p className="pr-key">المتوسّط {stats.avg ?? '—'} · اجتازوا {stats.pass_pct ?? '—'}% · يحتاجون دعمًا {stats.support_pct ?? '—'}% · {GRADE_KEY_AR} · الشواهد: {Object.values(EVIDENCE_MARKS_AR).join(' · ')}</p>
      <h2>٥ · {R4_NAMES_AR.attention}</h2>{b.attention.length ? <table><thead><tr><th>المتدرّب</th><th>السبب</th><th>القرار</th></tr></thead><tbody>{b.attention.map(a => <tr key={a.key}><th>{a.name}</th><td>{c.attention.find(x => x.key === a.key)?.reason || '—'}</td><td>{a.decision || '—'}</td></tr>)}</tbody></table> : <p className="pr-p">لم يُذكر أحد.</p>}
      <h2>٦ · ما تحقّق من الناتج</h2><p className="pr-p">{b.outcome.judgment || '—'}</p><p className="pr-key">نسبة من بلغوا الناتج: {b.outcome.pct ?? '—'}% · الشاهد: {b.outcome.evidence || '—'}</p>
      {b.next.support.length > 0 && <><h2>٧ · خطة الدعم</h2><table><thead><tr><th>المتدرّب</th><th>الدعم</th><th>من</th></tr></thead><tbody>{b.next.support.map(s => <tr key={s.key}><th>{s.name}</th><td>{s.what}</td><td>{s.owner}</td></tr>)}</tbody></table></>}
      {(b.next.adjust || b.next.admin) && <><h2>٨ · ما بعد الوحدة</h2>{b.next.adjust && <p className="pr-p">{b.next.adjust}</p>}{b.next.admin && <p className="pr-p">ملاحظة إدارية: {b.next.admin}</p>}</>}
      <table className="pr-sign"><thead><tr><th>المعلّم</th><th>اعتماد الطاقم</th></tr></thead><tbody><tr><td>{r.author_name || ''}</td><td>{r.approved_name || ''}{r.approved_at ? ` · ${fmtDayAr(String(r.approved_at).slice(0, 10))}` : ''}</td></tr></tbody></table>
      <footer className="pr-foot"><p>«{R4_NAMES_AR.story}» — {R4_NAMES_AR.motto}</p>{r.verify_code && <p>التحقّق: /verify/report/{r.verify_code}</p>}</footer>
    </article>
  </main>;
}

/* ───────── 6) خريطة الوحدات في صفحة البرنامج (عامّة) ───────── */
export function ProgramUnitsStrip({ programId }: { programId: string }) {
  const [units, setUnits] = useState<{ idx: number; title_ar: string; outcome_ar: string; hours: number; state: string }[] | null>(null);
  useEffect(() => { let on = true; fetch(`/api/reports?program_units=${encodeURIComponent(programId)}`, { cache: 'no-store' }).then(r => r.json()).then(j => { if (on) setUnits(j?.success ? j.units || [] : []); }).catch(() => { if (on) setUnits([]); }); return () => { on = false; }; }, [programId]);
  if (!units || !units.length) return null;
  const closed = units.filter(u => u.state === 'closed').length;
  return <section className="dr-strip" aria-labelledby="dr-strip-h" data-testid="dr-strip"><style dangerouslySetInnerHTML={{ __html: CSS }} />
    <h2 id="dr-strip-h"><Icon name="book" size={16} /> {R4_NAMES_AR.map} <small className="pt-muted">· {closed}/{units.length} أُغلقت بتقرير معتمَد</small></h2>
    <ol>{units.map(u => <li key={u.idx} data-state={u.state}><small>{STATE_MARK[u.state] || '○'} الوحدة {u.idx} · {UNIT_STATE_AR[u.state as keyof typeof UNIT_STATE_AR] || ''}{u.hours ? ` · ${u.hours} س` : ''}</small><b>{u.title_ar}</b>{u.outcome_ar && <p>{u.outcome_ar}</p>}</li>)}</ol>
  </section>;
}
